  "source_title": "hypertherm_powermax30_air_service_manual_rev4_808850.pdf",
  "nodes": {
    "Component": [
      {
        "component_id": "comp_power_supply",
        "name": "Power supply",
        "description": "The power supply assembly whose cover and component barrier are removed and installed.",
        "category": "power"
      },
      {
        "component_id": "comp_power_supply_cover",
        "name": "Power supply cover",
        "description": "The cover fitted over the power supply, aligned with the front and rear panels and the fan.",
        "category": "enclosure"
      },
      {
        "component_id": "comp_component_barrier",
        "name": "Component barrier",
        "description": "A flexible barrier installed on the power board side of the power supply, with its folded top edge covering the top of the power board.",
        "category": "protective"
      },
      {
        "component_id": "comp_front_panel",
        "name": "Front panel",
        "description": "The front panel aligned with the power supply and containing plastic notches that retain the component barrier.",
        "category": "enclosure"
      },
      {
        "component_id": "comp_rear_panel",
        "name": "Rear panel",
        "description": "The rear panel aligned with the power supply and containing plastic notches that retain the component barrier.",
        "category": "enclosure"
      },
      {
        "component_id": "comp_handle",
        "name": "Handle",
        "description": "The handle attached at the top of the power supply cover with two screws.",
        "category": "mechanical"
      },
      {
        "component_id": "comp_fan",
        "name": "Fan",
        "description": "The fan located behind the largest louvers in the power supply cover.",
        "category": "cooling"
      },
      {
        "component_id": "comp_power_board",
        "name": "Power board",
        "description": "The board on the power board side of the power supply, covered at the top by the component barrier.",
        "category": "electrical"
      },
      {
        "component_id": "comp_ground_clip",
        "name": "Ground clip",
        "description": "The ground clip whose hole is aligned with the screw holes in the rear panel and power supply during cover installation.",
        "category": "electrical"
      },
      {
        "component_id": "comp_plastic_base",
        "name": "Plastic base",
        "description": "The base with plastic notches that retain the bottom edge of the component barrier.",
        "category": "structural"
      }
    ],
    "Symptom": [],
    "FailureMode": [],
    "CorrectiveAction": [],
    "ErrorCode": []
  },
  "relations": []
}
